import json,hashlib,os
from pathlib import Path
roots=['/usr/local/bin','/usr/local/lib','/usr/bin','/opt/skilltta-verifier-v2','/root/.local/share/uv/tools/openhands','/usr/lib/jvm','/usr/share/maven','/opt/flink','/usr/local/lib/python3.12/dist-packages']
seen={};errors=[]
for root in roots:
 for p in Path(root).rglob('*'):
  if str(p) in seen or '__pycache__' in p.parts or p.suffix=='.pyc':continue
  try:
   if p.is_symlink():seen[str(p)]={'symlink':os.readlink(p)}
   elif p.is_file():
    h=hashlib.sha256()
    with p.open('rb') as f:
     for chunk in iter(lambda:f.read(1024*1024),b''):h.update(chunk)
    seen[str(p)]={'sha256':h.hexdigest(),'mode':p.stat().st_mode&0o7777}
  except Exception as e:errors.append({'path':str(p),'error':repr(e)})
print(json.dumps({'files':seen,'errors':errors},sort_keys=True))
